describe('Image Upload Error Handling', () => {
    beforeEach(() => {
        cy.visit('/upload'); // Replace with the actual URL of the upload page
    });

    it('should display an error message for images with dimensions too small', () => {
        const fileName = 'small-image.jpg'; // Replace with an actual small image file
        cy.fixture(fileName).then(fileContent => {
            cy.get('input[type="file"]').attachFile({ fileContent, fileName, mimeType: 'image/jpeg' });
        });
        cy.get('button[type="submit"]').click();
        cy.get('.error-message').should('be.visible').and('contain', 'Image dimensions are too small');
    });

    it('should not display an error message for images with valid dimensions', () => {
        const fileName = 'valid-image.jpg'; // Replace with an actual valid image file
        cy.fixture(fileName).then(fileContent => {
            cy.get('input[type="file"]').attachFile({ fileContent, fileName, mimeType: 'image/jpeg' });
        });
        cy.get('button[type="submit"]').click();
        cy.get('.error-message').should('not.exist');
    });
});
